{
  "spells": [
    {
      "id": "spell_wind_01",
      "theory": "招风术把微量魔力沿空气本身推开，形成两米内可见的流动，把烟雾从一处赶向别处。它只推动空气，不熄灭火源，也不驱散已经沉在角落的烟。湿气重的午后，气流会变沉，效果随之迟钝；干燥的河谷风则更容易接上。",
      "casting": "手掌向外摊开，指尖画一道短横，再缓缓侧推。推掌过快，气流会散成乱旋。",
      "failure": "常见失败是气流只在指缝间打转，烟反而被搅散到更宽处。若掌心出汗，招来的风会带一股潮气，把灰烬吹到邻近的布面上。",
      "counters": [
        "用厚毯压住烟源，气流便只能吹动表层空气。",
        "在逆风侧再招一股风，两股气流相撞后一同变弱。"
      ],
      "socialConsequences": "河谷乡民常在灶房或船篷里用它赶烟，事后会向在场的人说明是自家火塘。城里的面包师愿意借它散去烤炉溢烟，却担心街坊误以为失火。港务杂工用它吹开舱口积烟，货主若因此看到货损，仍会追究看管的人。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时气流方向常偏，可能把烟吹向自己。",
        "稍有把握后，能稳定把烟赶向一扇窗或舱口。",
        "熟练者能让风贴着地面走，减少扬起高处灰尘。",
        "更高熟练度下气流更匀，仍只限两米以内的烟。"
      ]
    },
    {
      "id": "spell_wind_02",
      "theory": "拂尘术让空气贴着物体表面快速滑过，带走松散尘土、草屑和干泥，却不能剥离渗进木纹或布料的污渍。魔力在物体上方形成一层薄气流，遇到有棱角的器物会绕行，因此边缝里的积灰常被留下。",
      "casting": "两指并拢，沿物体表面虚划一道弧线，再轻轻抬起。抬指太急，风会卷向旁边的人。",
      "failure": "若弧线划得太短，尘土只被推到物体一侧，堆成灰棱。碰到潮湿表面，风会把泥点甩到更远，留下斑驳的泥痕。",
      "counters": [
        "先用湿布盖住松散尘土，气流便只能吹动布面。",
        "在物体周围放下挡板，风被挡住后尘土落回原处。"
      ],
      "socialConsequences": "河谷嫁娶前，乡约会请人用拂尘术清理嫁妆箱笼，并当众说明灰土去处。城中抄写铺用它除纸面浮灰，但店主会先检查墨迹是否干透。港口的验货人借它查看木箱表面，货主若见尘土飞向他人货物，会要求重新清点。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时气流会吹动旁边轻纸，需先收好散页。",
        "掌握弧线后，能只清理桌面而不扬起架上灰尘。",
        "熟练者能控制气流贴着箱面走，减少灰尘飞散。",
        "更高熟练度下除尘更匀，但仍不能剥离牢固污渍。"
      ]
    },
    {
      "id": "spell_wind_03",
      "theory": "传声线把说话声压进一条短气流，让它沿指定方向传播。气流本身不辨敌友，沿途有人自然听得见。若中途被墙或厚帘挡住，声音会在遮挡处变闷，只剩零星词句。它不能把声音送到没有空气的地方。",
      "casting": "一手拢在嘴边，另一手向前伸出三指，低声说出要传的话。手放下太快，声音会散开。",
      "failure": "若拢嘴的手漏风，词句会变得含糊，听者只能听到尾音。气流被风吹偏时，声音可能落到无关的人耳中，传话者往往要当面解释。",
      "counters": [
        "在传声方向挂厚帘，声音被帘面挡下并变闷。",
        "用另一股短风横切气线，词句便被吹散成杂音。"
      ],
      "socialConsequences": "河谷集市上，摊主用传声线招呼远处同伴，乡约要求先确认不把私谈送进邻摊。城中商行用它叫回跑腿伙计，公会认为公开喊话不必许可，但传密约内容另算。港口调度借它通知泊位，若被无关船只听去，港务会追究传话人的疏忽。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时声音偏散，附近的人常先于目标听见。",
        "稍有控制后，能只让指定方向的人听清短句。",
        "熟练者可在嘈杂处压住杂音，仍须目标在三米内。",
        "更高熟练度下词句更清楚，不会增加传播距离。"
      ]
    }
  ]
}
